mapper.select:
SELECT u.id,u.id as userId,u.user_name,u.staffid,ur.create_time FROM uic_user_info u INNER JOIN aas_user_role ur on u.id = ur.user_id INNER JOIN aas_role_info r on ur.role_id = r.id INNER JOIN sys_config_info c on r.`name` = c.`value`
AND c.code =#{code}
AND r.tenant_id =#{tenantId}
AND u.user_name like concat('%',#{condition.userName},'%')
order by ur.create_time DESC,u.id DESC
